/// A themed elevation (`theme.<name>.elevation.<path>`).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u16)]
pub enum ElevationRole {
    /// `raised`
    Raised,
    /// `popover`
    Popover,
    /// `modal`
    Modal,
    /// `approval`
    Approval,
}

impl ElevationRole {
    /// Number of roles.
    pub const COUNT: usize = 4;
    /// Every role, in token-file order.
    pub const ALL: [ElevationRole; 4] = [
        ElevationRole::Raised,
        ElevationRole::Popover,
        ElevationRole::Modal,
        ElevationRole::Approval,
    ];
    /// The token path without the theme prefix, e.g. `fg.muted`.
    pub const fn path(self) -> &'static str {
        match self {
            ElevationRole::Raised => "raised",
            ElevationRole::Popover => "popover",
            ElevationRole::Modal => "modal",
            ElevationRole::Approval => "approval",
        }
    }
    /// Looks a role up by [`Self::path`].
    pub fn from_path(path: &str) -> Option<Self> {
        Some(match path {
            "raised" => ElevationRole::Raised,
            "popover" => ElevationRole::Popover,
            "modal" => ElevationRole::Modal,
            "approval" => ElevationRole::Approval,
            _ => return None,
        })
    }
}

